    {
      "id": "REQ-TESTABILITY",
      "result": "PASS",
      "severity": "Critical",
      "finding": "REQ-001–REQ-020 define verifiable selection, execution, rejection, provenance and delivery outcomes. AC-001–AC-020 and TEST-001–TEST-162 provide concrete validation branches, including configuration precedence and conflicts in TEST-152–TEST-162."
    },
    {
      "id": "GOAL-AC-TRACE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Acceptance Criteria maps every goal REQ-001–REQ-020 to its corresponding AC-001–AC-020. Test rows cover both CI and model workstreams, including expanded role coverage in TEST-138–TEST-146."
    },
    {
      "id": "AC-OBSERVABLE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Assertions specify inspectable plans, required contexts, aggregation failures, cache behavior, model selection records, launcher behavior and immutable tags. TEST-035, TEST-127 and TEST-133 explicitly distinguish verified execution from fixtures or unavailable telemetry."
    },
    {
      "id": "SCOPE-BOUNDARY",
      "result": "PASS",
      "severity": "Major",
      "finding": "Non-goals explicitly exclude external protection changes, privileged PR execution, new secrets/accounts, live cloud deployment, automatic merges, parent UI model control and historical evidence rewrites. Existing maintenance schedules and consent boundaries remain in scope without expansion."
    },
    {
      "id": "CONSTRAINTS-EXPLICIT",
      "result": "PASS",
      "severity": "Major",
      "finding": "Roles and Permissions, Security Boundaries, Model configuration precedence and REQ-014–REQ-019 specify trust, authorization, compatibility, native precedence, identity and consent constraints. OQ-001/OQ-002 define unavailable-validation behavior. Investigation contains no amendment declaration, but its historical baseline references do not establish premature later-phase work for this feature."
    },
    {
      "id": "RISK-VALIDATION-SURFACE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Dependency omissions, forged execution evidence and cache corruption have mutation/negative validation in TEST-014–TEST-030 and rollout comparisons in TEST-034–TEST-036. Model drift, fallback, privacy and adoption risks have TEST-082, TEST-100–TEST-115, TEST-131–TEST-133 and the pre-output Model Evaluation Boundary."
    },
    {
      "id": "DOMAIN-CONFORMANCE",
      "result": "SKIP",
      "severity": "Major",
      "finding": "The host states that the target project has no domain/ directory; investigation.md Bootstrap Context independently records its absence. The Approved-domain applicability condition is not met."
    }
  ]
